from math import gcd
from functools import reduce

def orient(shape):
    out=set()
    for refl in [False,True]:
        for k in range(4):
            pts=[]
            for r,c in shape:
                if refl: c=-c
                for _ in range(k): r,c=c,-r
                pts.append((r,c))
            mr=min(r for r,c in pts); mc=min(c for r,c in pts)
            out.add(tuple(sorted((r-mr,c-mc) for r,c in pts)))
    return out

def candidates(g):
    R,C=len(g),len(g[0]); pts8=[(r,c) for r in range(R) for c in range(C) if g[r][c]==8]
    colors=sorted({g[r][c] for r in range(R) for c in range(C)}-{0,8})
    # gcd contiguous runs of 8s
    lens=[]
    for r in range(R):
        n=0
        for c in range(C+1):
            if c<C and g[r][c]==8:n+=1
            elif n:lens.append(n);n=0
    for c in range(C):
        n=0
        for r in range(R+1):
            if r<R and g[r][c]==8:n+=1
            elif n:lens.append(n);n=0
    s=reduce(gcd,lens)
    r0=min(r for r,c in pts8); c0=min(c for r,c in pts8)
    mask=set()
    for r in range(r0,R,s):
      for c in range(c0,C,s):
        if all(r+dr<R and c+dc<C and g[r+dr][c+dc]==8 for dr in range(s) for dc in range(s)):
          mask.add(((r-r0)//s,(c-c0)//s))
    keys={col:[(r,c) for r in range(R) for c in range(C) if g[r][c]==col] for col in colors}
    patterns={co:orient(tuple((r-min(x for x,y in ps),c-min(y for x,y in ps)) for r,c in ps)) for co,ps in keys.items()}
    placements=[]
    for co,ori in patterns.items():
      for sh in ori:
        h=max(r for r,c in sh);w=max(c for r,c in sh)
        for dr in range(max(r for r,c in mask)+1):
          for dc in range(max(c for r,c in mask)+1):
            p=frozenset((r+dr,c+dc) for r,c in sh)
            if p<=mask: placements.append((co,p))
    sols=[]
    def search(covered, used, chosen):
      if covered==mask:
        if len(used)==len(colors): sols.append(chosen.copy())
        return
      if len(sols)>10000:return
      cell=min(mask-covered)
      for co,p in placements:
        if co not in used and cell in p and not (p&covered):
          search(covered|set(p),used|{co},chosen+[(co,p)])
    search(set(),set(),[])
    return s,r0,c0,mask,keys,sols
